/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.util.Locale;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;

/**
 * Page of the viewer ({@code /observe/}) and its login callback. The page has no data: it loads
 * {@code /observe/config/viewer-config.json}, logs in and calls {@code /observe/api}.
 */
@Path("observe")
@RequestScoped
@RequiredArgsConstructor
public class ObservePageController {

  private final ObservePageGateway pages;
  private final HttpHeaders headers;
  private final @ConfigProperty(name = "app.observe.viewer.title",
      defaultValue = "phylax-api") String title;
  private final @ConfigProperty(name = "app.observe.viewer.brand",
      defaultValue = "auto") String brand;

  @GET
  @Produces(MediaType.TEXT_HTML)
  public Response index() {
    return page();
  }

  @GET
  @Path("callback")
  @Produces(MediaType.TEXT_HTML)
  public Response callback() {
    return page();
  }

  private Response page() {
    Locale locale = headers.getAcceptableLanguages().stream().findFirst()
        .filter(l -> !"*".equals(l.getLanguage())).orElse(Locale.ENGLISH);
    String html =
        pages.getFullPage(title, ObservePages.fragment(title, brand, "auto"), locale, "app");
    return Response.ok(html).header("Cache-Control", "no-store")
        .header("Content-Security-Policy",
            "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; "
                + "img-src 'self' data:; connect-src *; frame-ancestors 'self'")
        .build();
  }
}
